import SwiftUI

struct ProfileView: View {
    @StateObject private var store = SocialStore(); @State private var notificationsOpen = false
    var body: some View { NavigationStack { Group { switch store.profileState { case .idle, .loading: ProgressView("Loading profile…"); case .failed(let message): RetryState(title: "Profile unavailable", message: message) { await store.loadProfile() }; case .empty: ContentUnavailableView("No profile", systemImage: "person"); case .loaded: if let profile = store.profile { profileBody(profile) } } }.background(PlumStyle.cream.ignoresSafeArea()).toolbar { ToolbarItem(placement: .topBarTrailing) { Button { notificationsOpen = true } label: { Image(systemName: "bell").foregroundStyle(.plum) }.accessibilityLabel("Notifications") } }.sheet(isPresented: $notificationsOpen) { NotificationsView(store: store) } }.task { await store.loadProfile() } }
    private func profileBody(_ profile: ProfileSnapshot) -> some View { ScrollView { VStack(spacing: 22) { VStack(spacing: 8) { Image(systemName: "person.crop.circle.fill").font(.system(size: 80)).foregroundStyle(.plum); Text(profile.displayName).font(.system(size: 27, weight: .semibold, design: .serif)); Text("@\(profile.username)\(profile.city.map { " · \($0)" } ?? "")").foregroundStyle(.secondary); if profile.visibility == .private { Label("Private account", systemImage: "lock.fill").font(.caption).foregroundStyle(.secondary) }; if let bio = profile.bio { Text(bio).multilineTextAlignment(.center) }; HStack { stat(profile.postCount, "posts"); stat(profile.collectionCount, "collections"); stat(profile.followerCount, "followers") } }.padding(.top, 12)
        NavigationLink { SocialActionsView() } label: { Label("Connections, messages & reports", systemImage: "person.2") }.buttonStyle(.bordered).tint(.plum)
        section("PHOTO DIARY") { LazyVGrid(columns: Array(repeating: GridItem(.flexible(), spacing: 4), count: 3), spacing: 4) { ForEach(profile.entries) { entry in AsyncImage(url: entry.photoURL) { $0.resizable().scaledToFill() } placeholder: { Rectangle().fill(Color.plum.opacity(0.12)).overlay(Image(systemName: "photo")) }.aspectRatio(1, contentMode: .fit).clipShape(RoundedRectangle(cornerRadius: 6)) } } }
        section("COLLECTIONS") { ForEach(profile.collections) { collection in HStack { Image(systemName: collection.rank == nil ? "bookmark" : "list.number").foregroundStyle(.plum); VStack(alignment: .leading) { Text(collection.title).font(.headline); Text("\(collection.itemCount) places or posts\(collection.isPublic ? " · Public" : " · Private")").font(.caption).foregroundStyle(.secondary) }; Spacer(); if let rank = collection.rank { Text("#\(rank)").font(.headline).foregroundStyle(.plum) } }.padding(12).background(.white, in: RoundedRectangle(cornerRadius: 14)) } }
    }.padding(.horizontal, 20).padding(.bottom, 32) } }
    private func stat(_ number: Int, _ label: String) -> some View { VStack { Text("\(number)").font(.headline); Text(label).font(.caption).foregroundStyle(.secondary) }.frame(maxWidth: .infinity) }
    private func section<Content: View>(_ title: String, @ViewBuilder content: () -> Content) -> some View { VStack(alignment: .leading, spacing: 10) { Text(title).font(.caption.weight(.bold)).foregroundStyle(.plum); content() } }
}

private struct NotificationsView: View {
    @ObservedObject var store: SocialStore
    var body: some View { NavigationStack { Group { switch store.notificationState { case .idle, .loading: ProgressView("Loading notifications…"); case .empty: ContentUnavailableView("You’re all caught up", systemImage: "bell"); case .failed(let message): RetryState(title: "Notifications unavailable", message: message) { await store.loadNotifications() }; case .loaded: List(store.notifications) { item in HStack { Image(systemName: symbol(item.kind)).foregroundStyle(.plum); VStack(alignment: .leading) { Text(item.title).font(.headline); Text(item.detail).font(.caption).foregroundStyle(.secondary) } } } } }.navigationTitle("Notifications") }.task { await store.loadNotifications() } }
    private func symbol(_ kind: SocialNotification.Kind) -> String { switch kind { case .like: "heart"; case .comment: "bubble.right"; case .reply: "arrowshape.turn.up.left"; case .follow: "person.badge.plus"; case .followRequest: "person.badge.clock"; case .followApproval: "checkmark.seal" } }
}
